from collections import defaultdict

def f(inputs: List[Tuple[int, int, List[Tuple[str, int, int]]]]) -> int:
    result = 0
    for n, h, operations in inputs:
        matrix = defaultdict(list)
        for ci, ai, bi in operations:
            matrix[(ai, bi)].append((ci, ai, bi))

        for xi, yi in matrix:
            if (xi, yi) in matrix and (yi, xi) in matrix:
                for ci, ai, bi in matrix[(xi, yi)]:
                    if ci == "xy":
                        result += ai * bi
                for ci, ai, bi in matrix[(yi, xi)]:
                    if ci == "yz":
                        result += ai * bi
            else:
                for ci, ai, bi in matrix[(xi, yi)]:
                    if ci == "xz":
                        result += ai * bi

    return result
```

